hors","where":{"slug":"notion"}}},"last_verified_at":"2026-10-13T00:00:00Z"},"priorRoute":{"slug":"simple-notion-alternatives","name":"Simple Notion Alternatives","description":"Draft comparison for the stated workflow. Candidate relationships and editions remain subject to review; publication is not approved.","anchor_id":{"$ref":{"table":"anchors","where":{"slug":"notion"}}},"status":"draft","editorially_approved":false,"last_verified_at":null},"priorMembers":[{"escape_route_id":{"$ref":{"table":"escape_routes","where":{"slug":"simple-notion-alternatives"}}},"product_id":{"$ref":{"table":"products","where":{"slug":"joplin"}}},"position":1,"editorial_note":"Draft review membership; not a publication decision."},{"escape_route_id":{"$ref":{"table":"escape_routes","where":{"slug":"simple-notion-alternatives"}}},"product_id":{"$ref":{"table":"products","where":{"slug":"logseq"}}},"position":3,"editorial_note":"Draft review membership; not a publication decision."},{"escape_route_id":{"$ref":{"table":"escape_routes","where":{"slug":"simple-notion-alternatives"}}},"product_id":{"$ref":{"table":"products","where":{"slug":"obsidian"}}},"position":2,"editorial_note":"Draft review membership; not a publication decision."}],"members":[{"productSlug":"joplin","position":1,"noveltyScore":0,"editorialNote":"Native desktop personal notebook and note capture/editing. No custom database, plugin or server is needed for this documented local flow. Markdown and optional sync require separate learning/setup; this is not Notion database, team-workspace or migration parity."},{"productSlug":"obsidian","position":2,"noveltyScore":0,"editorialNote":"Native desktop personal text notes in a named local vault, without community plugins or custom database configuration. Vault/Markdown concepts need learning; optional extensions, Sync and Publish add separate complexity or cost. No full Notion parity or tested migration is implied."},{"productSlug":"simplenote","position":3,"noveltyScore":0,"editorialNote":"Personal text-note editing and tag organization in the official desktop app after account signup. No custom database, plugin or server deployment is required for this documented flow. Signup/email verification and service connectivity are setup prerequisites; this does not promise local-only operation or Notion parity."}]}$pr525_data$::jsonb;
